import events from './events.json' with {type:'json'};

const TOOL_NAME = 'events_list';
const DEFAULT_PAGE_SIZE = 2;
const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;

function encodeCursor(index) {
  return Buffer.from(JSON.stringify({i:index}), 'utf8').toString('base64url');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    const json = Buffer.from(cursor, 'base64url').toString('utf8');
    parsed = JSON.parse(json);
  } catch (e) {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || !Number.isInteger(parsed.i)) {
    throw new Error('Unknown cursor');
  }
  if (parsed.i < 0 || parsed.i >= events.length) {
    throw new Error('Unknown cursor');
  }
  return parsed.i;
}

export async function listTools() {
  return [{
    name: TOOL_NAME,
    description: 'List events in source order with cursor-based pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string', description: 'Opaque pagination cursor returned from a previous call.' },
        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, description: 'Number of events per page (1-3, default 2).' }
      },
      additionalProperties: false
    }
  }];
}

export async function callTool(name, args = {}) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: ${name}`);
  }
  // Validate no extra fields
  const allowed = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!allowed.has(key)) {
      throw new Error(`Unknown argument: ${key}`);
    }
  }
  let cursor = args.cursor;
  if (cursor !== undefined) {
    if (typeof cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
  }
  let pageSize = args.page_size;
  if (pageSize === undefined) {
    pageSize = DEFAULT_PAGE_SIZE;
  } else {
    if (!Number.isInteger(pageSize) || pageSize < MIN_PAGE_SIZE || pageSize > MAX_PAGE_SIZE) {
      throw new Error(`page_size must be an integer between ${MIN_PAGE_SIZE} and ${MAX_PAGE_SIZE}`);
    }
  }
  let start = 0;
  if (cursor !== undefined) {
    start = decodeCursor(cursor);
  }
  const page = events.slice(start, start + pageSize);
  const result = { events: page };
  if (start + pageSize < events.length) {
    result.next_cursor = encodeCursor(start + pageSize);
  }
  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
